package dev.aster.charts;

import android.content.Context;import android.os.Looper;import org.json.*;
import java.nio.*;import java.lang.reflect.*;import java.util.*;import java.util.function.Consumer;

/** Public typed SDK functional cases. Raw columns use an explicitly private,
 * existing capture/readBuffer inspection seam, outside any measured window.
 */
final class IngestionVerification {
    private Context context;private AsterEngine source,witness;private Consumer<JSONObject> completion;
    private final JSONArray checks=new JSONArray(),jobs=new JSONArray();private boolean finished;
    private static final long T=1700000000000L;
    interface Action {void run()throws Exception;}
    private void check(boolean value,String label){if(!value)throw new AssertionError(label);checks.put(label);}
    private void code(String expected,Action action)throws Exception {boolean rejected=false;try{action.run();}catch(AsterEngine.IngestionException error){rejected=true;check(error.code.equals(expected)&&error.getMessage()!=null&&!error.getMessage().isEmpty(),"Typed ingestion error "+expected);}check(rejected,"Expected rejection "+expected);}
    private static JSONObject options()throws JSONException {return new JSONObject().put("panels",new JSONArray().put(new JSONObject().put("id","price"))).put("series",new JSONArray().put(new JSONObject().put("id","price").put("type","candles").put("panel","price")));}
    private static JSONObject bar(int index,double close)throws JSONException {double open=100+index*.02;return new JSONObject().put("time",T+index*60000L).put("open",open).put("high",Math.max(open,close)+1).put("low",Math.min(open,close)-1).put("close",close).put("volume",100+index);}
    private static JSONObject event(String kind,int index,double close)throws JSONException {return new JSONObject().put("kind",kind).put("bar",bar(index,close));}
    private static JSONArray bars(int count)throws JSONException {JSONArray result=new JSONArray();for(int i=0;i<count;i++)result.put(bar(i,100+i*.02+(i%2==0?.125:-.125)));return result;}
    private static JSONObject packet(String stream,long sequence,JSONArray events)throws JSONException {return new JSONObject().put("streamId",stream).put("generation",1).put("firstSequence",sequence).put("events",events);}
    private static JSONObject policy(String stream,int maxBars)throws JSONException {return new JSONObject().put("streamId",stream).put("generation",1).put("firstSequence",100).put("maxQueuedEvents",3).put("maxQueuedBytes",147).put("maxBatchEvents",2).put("maxStoredBars",maxBars).put("maxStoreBytes",96*1024);}
    private static JSONObject state(AsterEngine engine)throws JSONException {return (JSONObject)engine.command("inspect");}
    private void conserved(JSONObject stats,String reason)throws JSONException {check(stats.getLong("accepted")==stats.getLong("applied")+stats.getLong("cancelled")+stats.getLong("pendingEvents")&&stats.getLong("pendingBytes")==49*stats.getLong("pendingEvents"),reason);}
    void run(Context context,Consumer<JSONObject> completion){this.context=context;this.completion=completion;try{check(Looper.myLooper()==Looper.getMainLooper(),"Functional fixture main owner");witness=new AsterEngine(context,0,options());testSync();testVectors();source=new AsterEngine(context,6,options());source.configureDataIngestion(policy("async",1024));testCancel();}catch(Throwable error){finish(error);}}
    private void testSync()throws Exception {
        try(AsterEngine e=new AsterEngine(context,0,options())){
            e.setData(bars(5));final int[] notifications={0};e.addChangeListener(()->notifications[0]++);long revision=e.revision();
            JSONObject receipt=e.applyDataEvents(new JSONArray().put(event("append",5,13)).put(event("update",5,14)).put(event("correction",2,15)));
            check(receipt.getInt("events")==3&&receipt.getInt("appended")==1&&receipt.getInt("from")==2&&receipt.getInt("to")==6&&receipt.getInt("length")==6&&e.revision()==revision+1&&notifications[0]==1,"Atomic public burst receipt and one host notification");
            String before=state(e).toString();revision=e.revision();int observed=notifications[0];boolean rejected=false;
            try{e.applyDataEvents(new JSONArray().put(event("update",5,16)).put(event("append",5,99)));}catch(IllegalStateException error){rejected=true;check(!(error instanceof AsterEngine.IngestionException),"Legacy batch keeps generic data error boundary");}
            check(rejected&&before.equals(state(e).toString())&&e.revision()==revision&&notifications[0]==observed,"Invalid batch keeps data/revision/notification unchanged");
            JSONObject configured=e.configureDataIngestion(policy("small",6));check(configured.getLong("ownedBytes")==147&&configured.getString("state").equals("running"),"Configured bounded F64/U8 ring reports actual owned bytes");
            JSONObject owned=packet("small",100,new JSONArray().put(event("update",5,16)).put(event("correction",0,8)));JSONObject admitted=e.enqueueDataEvents(owned);owned.getJSONArray("events").getJSONObject(0).getJSONObject("bar").put("volume",999999);owned.put("firstSequence",999);
            check(admitted.getInt("events")==2&&admitted.getLong("firstSequence")==100&&admitted.getLong("nextSequence")==102,"Whole packet admission cursors");
            revision=e.revision();observed=notifications[0];String saved=e.saveDataIngestion();JSONObject stats=e.dataIngestionStats();conserved(stats,"Queued conservation before drain");check(e.revision()==revision&&notifications[0]==observed&&stats.getLong("pendingEvents")==2&&stats.getLong("pendingBytes")==98,"Stats/save are readonly and distinguish logical pending bytes");
            e.pauseDataIngestion();revision=e.revision();observed=notifications[0];code("PAUSED",()->e.enqueueDataEvents(packet("small",102,new JSONArray().put(event("update",5,17)))));check(e.revision()==revision&&notifications[0]==observed,"Rejected queue mutation does not notify");
            JSONObject cancelled=e.cancelDataEvents();check(cancelled.getLong("events")==2&&cancelled.getLong("firstSequence")==100&&cancelled.getLong("lastSequence")==101,"Explicit cancel receipt retains accepted cursor");
            JSONObject loaded=e.loadDataIngestion(saved);check(loaded.getLong("pendingEvents")==2&&loaded.getLong("nextSequence")==102&&loaded.getString("state").equals("running"),"Saved owned queue restored atomically against existing base history");
            code("SEQUENCE_MISMATCH",()->e.enqueueDataEvents(packet("small",101,new JSONArray().put(event("update",5,17)))));
            JSONObject first=e.drainDataEvents(1);check(first.getInt("events")==1&&first.getLong("firstSequence")==100&&first.getLong("lastSequence")==100&&state(e).getJSONObject("lastBar").getLong("volume")==105,"Drain prefix/sequence and caller payload copy ownership");
            JSONObject second=e.drainDataEvents();check(second.getInt("events")==1&&second.getLong("firstSequence")==101&&e.dataIngestionStats().getLong("applied")==2,"Default drain applies ordered remaining prefix");
            e.enqueueDataEvents(packet("small",102,new JSONArray().put(event("append",6,18))));before=state(e).toString();revision=e.revision();observed=notifications[0];code("DRAIN_FAILED",e::drainDataEvents);JSONObject failed=e.dataIngestionStats();check(failed.getString("state").equals("paused")&&failed.getLong("pendingEvents")==1&&failed.getLong("failedDrains")==1&&before.equals(state(e).toString())&&e.revision()==revision&&notifications[0]==observed,"Finite store budget failure keeps prefix/data and pauses without publication");
            code("PAUSED",e::drainDataEvents);e.cancelDataEvents();e.resumeDataIngestion();conserved(e.dataIngestionStats(),"Explicit cancel/resume restores conserved running session");
            String stable=e.saveDataIngestion();JSONObject bad=new JSONObject(stable);bad.getJSONObject("counters").put("accepted",99);code("INVALID_DOCUMENT",()->e.loadDataIngestion(bad.toString()));check(stable.equals(e.saveDataIngestion()),"Invalid saved counters preserve current session");
            final Throwable[] wrong={null};Thread caller=new Thread(()->{try{e.enqueueDataEvents(new JSONObject());}catch(Throwable error){wrong[0]=error;}});caller.start();caller.join();check(wrong[0]!=null&&wrong[0].getClass()==IllegalStateException.class,"Owner check precedes typed input/ingestion guard");
        }
    }
    private void testVectors()throws Exception {
        String[] names={"sma","ema","bollinger","macd","donchian","stochastic","rsi","atr"};JSONArray initial=bars(512),events=new JSONArray().put(event("update",511,112)).put(event("append",512,114)).put(event("correction",256,109)).put(event("update",512,116));
        try(AsterEngine batch=new AsterEngine(context,0,options());AsterEngine scalar=new AsterEngine(context,0,options())){
            batch.setData(initial);scalar.setData(initial);Map<String,JSONArray> outputs=new LinkedHashMap<>();for(String name:names){outputs.put(name,(JSONArray)batch.invoke("nativeIndicator",name,name,new JSONObject(),"price"));scalar.invoke("nativeIndicator",name,name,new JSONObject(),"price");}
            for(AsterEngine engine:new AsterEngine[]{batch,scalar}){String id=engine.addDrawing(new JSONObject().put("id","ingestion-line").put("type","trendline").put("panel","price").put("points",new JSONArray().put(new JSONObject().put("time",T+256*60000L).put("price",100)).put(new JSONObject().put("time",T+300*60000L).put("price",105))));engine.editDrawing(id,new JSONObject().put("text","ordered burst"));engine.selectDrawing(id);}String drawings=batch.saveDrawings();
            batch.applyDataEvents(events);for(int i=0;i<events.length();i++)scalar.applyDataEvent(events.getJSONObject(i));int count=0;for(Map.Entry<String,JSONArray> row:outputs.entrySet())for(int i=0;i<row.getValue().length();i++){String output=row.getValue().getString(i);check(Arrays.equals(batch.indicatorBytes(row.getKey(),output,0,513),scalar.indicatorBytes(row.getKey(),output,0,513)),"All full Float64 vector bytes batch/scalar "+row.getKey()+"/"+output);count++;}check(count==15,"Eight builtin definitions expose exactly15 vectors");
            JSONArray expected=new JSONArray(initial.toString());expected.put(511,bar(511,112));expected.put(bar(512,116));expected.put(256,bar(256,109));rawColumns(batch,expected);check(state(batch).getJSONObject("view").toString().equals(state(scalar).getJSONObject("view").toString()),"Atomic appended burst follows final tail once");check(drawings.equals(batch.saveDrawings())&&drawings.equals(scalar.saveDrawings()),"Burst preserves raw drawing anchors/selection/history");batch.undo();scalar.undo();check(batch.saveDrawings().equals(scalar.saveDrawings()),"Burst adds no drawing undo entry");batch.redo();check(drawings.equals(batch.saveDrawings()),"Redo restores exact pre-burst drawing document");
        }
    }
    private void rawColumns(AsterEngine engine,JSONArray expected)throws Exception {
        JSONObject event=new JSONObject().put("kind","correction").put("bar",expected.getJSONObject(0));JSONObject capture=new JSONObject((String)engine.invoke("nativeAsyncBegin",event.toString()));long ticket=capture.getLong("ticket");try{
            JSONObject metadata=new JSONObject(capture.getString("metadataJSON")),store=metadata.getJSONObject("store"),columns=store.getJSONObject("columns");check(store.getInt("length")==expected.length(),"Private capture raw length matches replayed source");Field handle=AsterEngine.class.getDeclaredField("handle");handle.setAccessible(true);Method read=AsterEngine.class.getDeclaredMethod("readBuffer",long.class,long.class,int.class,int.class,int.class);read.setAccessible(true);String[] keys={"time","open","high","low","close","volume"};
            for(String key:keys){int slot=columns.getJSONObject(key).getInt("buffer");check(capture.getJSONArray("buffers").getJSONObject(slot).getInt("slot")==slot&&capture.getJSONArray("buffers").getJSONObject(slot).getInt("length")>=expected.length(),"Private capture actual buffer descriptor "+key);engine.invoke("nativeAsyncCheck",ticket);byte[] bytes=(byte[])read.invoke(null,handle.getLong(engine),ticket,slot,0,expected.length());ByteBuffer values=ByteBuffer.wrap(bytes).order(ByteOrder.nativeOrder());for(int i=0;i<expected.length();i++)if(Double.doubleToRawLongBits(values.getDouble())!=Double.doubleToRawLongBits(expected.getJSONObject(i).getDouble(key)))throw new AssertionError("Raw replay "+key+"/"+i);checks.put("Private existing typed-copy full raw column "+key);}
        }finally{engine.invoke("nativeAsyncRelease",ticket);}
    }
    private AsterEngine.AsyncListener listener(String label,Consumer<AsterEngine.AsyncResult> next){final int[] terminals={0};return new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress progress){if(Looper.myLooper()!=Looper.getMainLooper()||terminals[0]!=0)finish(new AssertionError(label+" progress ownership/afterterminal"));}@Override public void onComplete(AsterEngine.AsyncResult result){try{check(Looper.myLooper()==Looper.getMainLooper()&&++terminals[0]==1,label+" owner/exactly-once completion");jobs.put(result.toJSON());next.accept(result);}catch(Throwable error){finish(error);}}};}
    private void testCancel()throws Exception {
        String saved=source.saveDataIngestion();AsterEngine.AsyncJob job=source.prepareSeededAsync(32,42,16,listener("cancel",result->{try{check(result.status.equals("cancelled")&&saved.equals(source.saveDataIngestion()),"Cancelled prepare releases lease and preserves session");testCommittedObserver();}catch(Throwable error){finish(error);}}));
        code("BUSY",source::pauseDataIngestion);code("BUSY",()->source.command("cancelDataEvents"));code("BUSY",()->source.configureDataIngestion(new JSONObject()));code("BUSY",()->source.enqueueDataEvents(new JSONObject()));code("BUSY",source::drainDataEvents);code("BUSY",source::resumeDataIngestion);code("BUSY",()->source.loadDataIngestion("bad"));long revision=source.revision();source.dataIngestionStats();source.saveDataIngestion();check(source.revision()==revision,"Lease stats/save remain readonly during host early gap");job.cancel();
    }
    private void testCommittedObserver()throws Exception {
        final boolean[] armed={true};final Throwable[] observed={null};final AsterEngine.AsyncJob[] job={null};Runnable observer=()->{if(!armed[0])return;armed[0]=false;try{JSONObject stats=source.dataIngestionStats(),last=state(source).getJSONObject("lastBar");JSONObject update=new JSONObject(last.toString());update.put("volume",last.getDouble("volume")+1);source.enqueueDataEvents(packet("async",stats.getLong("nextSequence"),new JSONArray().put(new JSONObject().put("kind","update").put("bar",update))));source.pauseDataIngestion();source.cancelDataEvents();job[0].cancel();}catch(Throwable error){observed[0]=error;}};source.addChangeListener(observer);
        job[0]=source.prepareSeededAsync(32,42,16,listener("success",result->{try{source.removeChangeListener(observer);check(result.succeeded()&&!armed[0]&&observed[0]==null&&source.observerErrors().isEmpty(),"Committed observer enqueue/pause/cancel allowed before job cleanup");JSONObject stats=source.dataIngestionStats();conserved(stats,"Committed observer accounting conserved");check(stats.getLong("accepted")==1&&stats.getLong("cancelled")==1&&stats.getLong("pendingEvents")==0&&stats.getString("state").equals("paused"),"Ingestion counters/policy survive prepared context handoff");source.resumeDataIngestion();testPending();}catch(Throwable error){finish(error);}}));
    }
    private void testPending()throws Exception {
        JSONObject stats=source.dataIngestionStats(),last=state(source).getJSONObject("lastBar");source.enqueueDataEvents(packet("async",stats.getLong("nextSequence"),new JSONArray().put(new JSONObject().put("kind","update").put("bar",last))));String before=source.saveDataIngestion();source.prepareSeededAsync(32,42,16,listener("pending",result->{try{check(result.status.equals("failed")&&result.error instanceof AsterEngine.IngestionException&&((AsterEngine.IngestionException)result.error).code.equals("PENDING_DATA")&&before.equals(source.saveDataIngestion()),"Pending source rejects async with typed PENDING_DATA and no lost payload");source.cancelDataEvents();testClose();}catch(Throwable error){finish(error);}}));
    }
    private void testClose()throws Exception {source.prepareSeededAsync(32,42,16,listener("close",result->{try{check(result.status.equals("closed"),"Close cancels isolated work exactly once");boolean rejected=false;try{source.dataIngestionStats();}catch(IllegalStateException error){rejected=error.getClass()==IllegalStateException.class;}check(rejected,"Closed owner check retains legacy priority");source=null;finish(null);}catch(Throwable error){finish(error);}}));source.close();}
    private void finish(Throwable error){if(finished)return;finished=true;JSONObject runtime=new JSONObject();
        try{if(source!=null){source.close();source=null;}if(witness!=null)runtime=witness.runtimeMetrics();if(error==null)check(runtime.getLong("processLiveNativeHandles")==1&&runtime.getLong("processNativeHandlesCreated")-runtime.getLong("processNativeHandlesFreed")==1,"All source/reference/worker handles settled before witness close");}catch(Throwable cleanup){if(error==null)error=cleanup;}
        finally{if(witness!=null)try{witness.close();}catch(Throwable cleanup){if(error==null)error=cleanup;}finally{witness=null;}}
        try{JSONObject report=new JSONObject().put("passed",error==null).put("checks",checks).put("checkCount",checks.length()).put("jobs",jobs).put("runtimeBeforeWitnessClose",runtime).put("scope","Actual public Java typed SDK + JNI/QuickJS functional only. Private reflection raw column capture uses metadata slot mapping/check/release, separately labelled. No Activity/system input/timing/900s run.").put("physicalDevice",false);if(error!=null)report.put("error",error.toString());completion.accept(report);}catch(JSONException failure){throw new IllegalStateException(failure);}
    }
}
